INSERT INTO workweave.knowledge_chunks (chunk_id, organization_id, workspace_id, document_version_id, source_id, parent_chunk_id, section_path, heading, content, chunk_index, source_span, embedding, embedding_model, embedding_dimension, index_generation, metadata, created_at, updated_at, revision, source_section_id) VALUES ('5bf4dd3d-c985-4cc5-9400-f2cb9ecac95f', '00000003-0000-4000-8000-000000000001', '00000003-0000-4000-8000-000000000002', '00000003-0000-4000-8000-000000000971', '00000003-0000-4000-8000-000000000970', NULL, '["Fundamentals"]'::jsonb, 'Introduction', '#### 1.4 Roles

- **Engineer:** prepares and runs the change, records evidence, reports results.
- **Shift lead:** reviews the plan, decides on go or stop when evidence is unclear, approves a rollback within the change process.
- **Change approver:** approves the change window before anything starts.
